   Time.timeScale=1;Check(m.Finished&&m.series.completed>=3&&m.series.winner>=0,"actual autonomous series resolves authoritative ranks and winner");Check(totalFinishes>=12,"all four pairs physically finish each of three races");report.AppendLine("METRICS finishes="+totalFinishes+" totalDrops="+totalDrops+" sampleMeanDrivingSpeed="+(speedSamples==0?0:speedSum/speedSamples)+" samples="+speedSamples+" races="+m.series.completed+" winner="+m.series.winner+" scores="+string.Join(",",m.series.total));m.SetupScreen();Check(m.StartMatch()&&m.Clock==0&&m.series.completed==0&&m.pairs[0].Drops==0,"rematch resets race, scores, load joints and drop counters");m.SetupScreen();SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<WifeMatch>()==null&&FindObjectsByType<AudioListener>().Length==1,"collection return releases scene and audio ownership");report.AppendLine("CHECKS="+checks+" ERRORS="+errors+". Actual four-pair NWH/PhysX AI races with fixed timestep and accelerated test presentation; no human/hardware/Windows claim.");File.WriteAllText(folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;
